    if (g.status !== 'online' || !Number.isFinite(age) || age < 0 || age > 4500) return 'Unknown (stale status)';
    if (typeof g.limitOpenActive !== 'boolean' || typeof g.limitCloseActive !== 'boolean') return 'Unknown';
    return !g.limitOpenActive && !g.limitCloseActive ? 'Limit conflict'
        : !g.limitOpenActive ? 'Open' : !g.limitCloseActive ? 'Closed' : 'Between limits';
}
function operationOwners() {
    return (global.get('zoo_gates') || []).filter(g => g.lockedBy).map(g => ({
        id: g.id, name: g.name, user: g.lockedBy,
        device: g.lockedDevice || 'Unknown device', lease: g.controlLeaseId, position: operationPosition(g)
