    const user = (global.get('zoo_client_map') || {})[msg.socketid];
    for (const gate of gates) {
        if (gate.lockedBy === user && gate.lockedSession === msg.socketid &&
            sessions[user] === msg.socketid &&
            (!msg.payload.gateId || msg.payload.gateId === gate.id)) {
            gate.controlHeartbeatAt = now;
        }
    }
    global.set('zoo_gates', gates);
    return null;
}
const diagnostics = [];
const auditMessages = [];
const quoteSql = value => String(value).replace(/'/g, "''");
for (const gate of gates) {
    if (!gate.lockedBy) {
        if (commands[gate.id]) {
            commands[gate.id] = { OPEN: false, CLOSE: false, ESTOP: false, KEY: false, ENERGIZE: false, HEARTBEAT: false };
        }
        continue;
    }
    const user = gate.lockedBy;
    const owner = gate.lockedSession;
    const age = now - (gate.controlHeartbeatAt || 0);
    const alive = Boolean(owner) && sessions[user] === owner && age >= 0 && age <= 3000;
    if (!commands[gate.id]) commands[gate.id] = {};
    commands[gate.id].HEARTBEAT = alive;
    if (!alive) {
        const device = gate.lockedDevice;
        const held = ['OPEN', 'CLOSE', 'ENERGIZE'].filter(key => commands[gate.id][key] === true);
        const operation = held.length
            ? ` CRITICAL: Connection lost WHILE OPERATING! Active remote commands: ${held.join(', ')}.`
            : ' No active remote operation was observed.';
        const text = `Control session lost on gate '${gate.name}' (${gate.id}).` + operation +
            ` Operator: ${user}. Device: ${device || 'Unknown'}. Gate released and command memory cleared.`;
        const type = held.length ? 'error' : 'warning';
        const timestamp = new Date(now).toISOString().slice(0, 19).replace('T', ' ');
        auditMessages.push({ topic: `INSERT INTO audit_logs (timestamp, category, user, type, text) VALUES ('${timestamp}', 'AUTH', '${quoteSql(user)}', '${type}', '${quoteSql(text)}');` });
        releaseGate(gate);
        commands[gate.id] = { OPEN: false, CLOSE: false, ESTOP: false, KEY: false, ENERGIZE: false, HEARTBEAT: false };
        if (sessions[user] === owner) {
            delete sessions[user];
            const map = global.get('zoo_client_map') || {};
            delete map[owner];
            global.set('zoo_client_map', map);
            if (String(owner).startsWith('tablet_')) {
                const flags = global.get('zoo_force_logout') || {};
                flags[user] = { at: now, reason: 'Gate control connection lost. Please sign in again.' };
                global.set('zoo_force_logout', flags);
            }
        }
        const logs = global.get('zoo_audit_logs') || [];
        logs.unshift({ time: new Date().toLocaleTimeString(), user,
            text, type, category: 'AUTH', device });
        if (logs.length > 500) logs.pop();
        global.set('zoo_audit_logs', logs);
    }
    diagnostics.push({ payload: { action: 'roaming_diag', user, gateId: gate.id, age,
        status: alive ? (age <= 1200 ? 'Excellent' : 'Degraded') : 'Stalled / Disconnected',
        color: alive ? (age <= 1200 ? '#4ade80' : '#fbbf24') : '#ef4444' } });
