global.set('zoo_active_commands', commands);
global.set('zoo_active_sessions', sessions);
return [null, diagnostics.length ? diagnostics :
    { payload: { action: 'roaming_diag', user: 'None', age: 0, status: 'No Active Lock', color: '#777777' } },
    auditMessages.length ? auditMessages : null];
