const operationAfter = operationOwners();
if (JSON.stringify(operationBefore.map(g => [g.id, g.user, g.device, g.lease])) ===
    JSON.stringify(operationAfter.map(g => [g.id, g.user, g.device, g.lease])) && !operationCommands.length) {
    return operationResult;
}
const operationOutputs = Array.isArray(operationResult) ? operationResult : [operationResult];
operationOutputs[3] = {
    operation: {
        before: operationBefore, after: operationAfter, commands: operationCommands,
        action: operationAction || 'server cleanup', source: "watchdog", at: Date.now()
    }
